// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);
        Proxy proxy = new Proxy(c);
        vm.prank(address(this));
        c.setOwner(address(proxy));
        vm.prank(caller);
        proxy.forward(newOwner);
        bool success = false;
        try c.setOwner(newOwner) returns (bool) { success = true; } catch { success = false; }
        assertTrue(c.owner() != caller);
    }
}

contract Proxy {
    Owned public target;
    constructor(Owned _target) { target = _target; }
    function forward(address newOwner) external { target.setOwner(newOwner); }
}
